package main

import (
	"strconv"

	consolemeta "github.com/moedove/ixp-manager/internal/console"
)

// The documented console tables gained nullable created_at/updated_at columns
// in 2020. created/updated are explicit adapted-export aliases, not inferred
// first-seen times. Source text has no assumed zone; current Go entity dates
// are still generated by resource import and are never copied from this data.
func (c *converter) consoleTimestamps(table string, source, out row) error {
	values := row{}
	for _, field := range []struct{ current, alias, target string }{
		{"created_at", "created", "createdAt"},
		{"updated_at", "updated", "updatedAt"},
	} {
		var selected any
		present := false
		for _, key := range []string{field.current, field.alias} {
			value, exists := source[key]
			if !exists {
				continue
			}
			c.consoleUsed(table, source, key)
			if value != nil {
				text, ok := value.(string)
				if !ok || consolemeta.ValidateSourceTimestamp(text) != nil {
					return c.consoleError(table, source, key+" must be null, a valid SQL datetime (optional 1..6 fractional digits), its explicit all-zero sentinel, or RFC3339 with an offset; correct the source value without inventing a timezone")
				}
			}
			// Values are now string or nil, so exact comparison preserves both
			// source spelling/precision and missing-versus-explicit-null evidence.
			if present && selected != value {
				return c.consoleError(table, source, "conflicting "+field.current+" and "+field.alias+" timestamp aliases; reconcile the source export")
			}
			selected, present = value, true
		}
		if present {
			values[field.target] = selected
		}
	}
	if len(values) != 0 {
		values["sourceId"] = strconv.FormatInt(idOf(source), 10)
		out["legacyTimestamps"] = values
	}
	return nil
}
